  getPrivilegesCounts() {
    try {
      const overview = this.getPrivilegesOverview();
      const counts = { total: overview.length, view: 0, add: 0, edit: 0, delete: 0 };
      for (const p of overview) {
        if (p.view) counts.view++;
        if (p.add) counts.add++;
        if (p.edit) counts.edit++;
        if (p.delete) counts.delete++;
      }
      return counts;
    } catch (e) { return { total: 0, view: 0, add: 0, edit: 0, delete: 0 }; }
  }

  // navigate step helper used by review edit buttons
  goToStep(stepper: any, index: number) {
    try { if (stepper && typeof stepper.selectedIndex !== 'undefined') stepper.selectedIndex = index; } catch (e) { }
  }


  passwordsMatch(group: FormGroup) {
    const pwd = group.get('password');
    const confirmPwd = group.get('confirmPassword');
    if (!pwd || !confirmPwd) return null;

    const p = pwd.value || '';
    const c = confirmPwd.value || '';

    if (!p && !c) {
      if (confirmPwd.hasError('passwordMismatch')) {
        const errors = { ...confirmPwd.errors };
        delete errors['passwordMismatch'];
        confirmPwd.setErrors(Object.keys(errors).length ? errors : null);
      }
      return null;
    }

    if (p !== c) {
      if (!confirmPwd.hasError('passwordMismatch')) {
        confirmPwd.setErrors({ ...confirmPwd.errors, passwordMismatch: true });
      }
      return { passwordMismatch: true };
    } else {
      if (confirmPwd.hasError('passwordMismatch')) {
        const errors = { ...confirmPwd.errors };
        delete errors['passwordMismatch'];
        confirmPwd.setErrors(Object.keys(errors).length ? errors : null);
      }
      return null;
    }
  }

  back() {
    sessionStorage.removeItem('edit_user');
    this.router.navigate(['/view-users']);
  }

  submit(stepper?: any) {
    if (this.submitting) {
      return;
    }

    if (this.isEditing) {
      const pwd = this.form.get('password')?.value;
      const cpwd = this.form.get('confirmPassword')?.value;
      if (!pwd && !cpwd) {
        this.form.get('password')?.clearValidators();
        this.form.get('password')?.updateValueAndValidity({ emitEvent: false });
        this.form.get('confirmPassword')?.clearValidators();
        this.form.get('confirmPassword')?.updateValueAndValidity({ emitEvent: false });
      }
    }

    if (this.form.invalid) {
      this.submitting = false;
      this.form.markAllAsTouched();
      this.loader.hide();

      const invalidControls: string[] = [];
      Object.keys(this.form.controls).forEach((key) => {
        const ctrl = this.form.get(key);
        if (ctrl && ctrl.invalid) {
          invalidControls.push(key);
        }
      });

      console.warn('Cannot submit form. Invalid controls:', invalidControls, this.form.errors);

      const fieldLabels: Record<string, string> = {
        name: 'Full Name',
        username: 'User Name',
        email: 'Email',
        password: 'Password',
        confirmPassword: 'Confirm Password',
        joining_date: 'Joining Date',
        institute: 'Institute',
        role: 'Role',
        department: 'Department',
        team: 'Team',
        phone: 'Phone',
      };

      const step1Fields = ['name', 'username', 'email', 'password', 'confirmPassword', 'joining_date', 'phone'];
      const step2Fields = ['institute', 'role', 'department', 'team', 'campus', 'country', 'state', 'city'];

      const firstInvalidKey = invalidControls[0];
      const errorLabel = fieldLabels[firstInvalidKey] || firstInvalidKey || 'required fields';

      if (invalidControls.some((f) => step1Fields.includes(f))) {
        this.goToStep(stepper, 0);
      } else if (invalidControls.some((f) => step2Fields.includes(f))) {
        this.goToStep(stepper, 1);
      }

      this.notify.error(`Please correct the field "${errorLabel}" before saving.`);
      return;
    }

    this.loader.show();
    const v = this.form.value;
    const currentUserRaw = sessionStorage.getItem('user') || sessionStorage.getItem('user_profile');
    let current_user: any = null;
    try { current_user = currentUserRaw ? JSON.parse(currentUserRaw) : null; } catch (e) { current_user = currentUserRaw || null; }
    let formattedJoiningDate: string | null = null;
    if (v.joining_date instanceof Date && !isNaN(v.joining_date.getTime())) {
      const y = v.joining_date.getFullYear();
      const m = String(v.joining_date.getMonth() + 1).padStart(2, '0');
      const d = String(v.joining_date.getDate()).padStart(2, '0');
      formattedJoiningDate = `${y}-${m}-${d}`;
    } else if (typeof v.joining_date === 'string' && v.joining_date.trim()) {
      const trimmed = v.joining_date.trim();
      if (/^\d{2}[-\/]\d{2}[-\/]\d{4}$/.test(trimmed)) {
        const parts = trimmed.split(/[-\/]/);
        formattedJoiningDate = `${parts[2]}-${parts[1]}-${parts[0]}`;
      } else {
        formattedJoiningDate = trimmed;
      }
    }

    const payload: any = {
      // prefer sending both username and display name
      user_name: v.username || v.name,
      display_name: v.name,
      full_name: v.name,
      email: v.email,
      user_role: v.role,
      institute_id: v.institute,
      campus_id: v.campus || null,
      country_id: v.country || null,
      state_id: v.state || null,
      city_id: v.city || null,
      department_id: v.department || null,
      team_id: v.team || null,
      joining_date: formattedJoiningDate,
      contact_no: v.phone,
      active_status: v.active,
      note: v.note,
      current_user: (current_user && (current_user.user_id || current_user.id)) ? (current_user.user_id || current_user.id) : null
    };

    if (v.password && String(v.password).trim()) {
      payload.password = String(v.password).trim();
    }

    // include page-level permissions if any
    try {
      const pages: any[] = [];
      Object.keys(this.pagesPermissions || {}).forEach(k => {
        const p = this.pagesPermissions[k];
        pages.push({ page_key: k, view: !!p.view, add: !!p.add, edit: !!p.edit, delete: !!p.delete });
      });
      if (pages.length) payload.page_access = pages;
    } catch (e) { }
    this.submitting = true;

    if (this.isEditing && this.editingUserId) {
      // update existing user
      const url = `${API_BASE}/update-user/${this.editingUserId}`;
      this.http.put<any>(url, payload).subscribe({
        next: (res) => {
          this.submitting = false;
          this.loader.hide();
          sessionStorage.removeItem('edit_user');
          this.notify.success(res?.statusMessage || 'User updated successfully');
          this.router.navigate(['/view-users']);
        },
        error: (err) => {
          this.submitting = false;
          this.loader.hide();
          console.error('Update failed', err);
          const serverMsg = err?.error?.statusMessage || err?.error?.message || err?.statusMessage || err?.message;
          this.notify.error(serverMsg ? `Failed to update user: ${serverMsg}` : 'Failed to update user.');
        }
      });
    } else {
      const url = `${API_BASE}/register-user`;
      if (!this.isSuperAdmin && this.loggedInstitute) {
        payload.institute_id = this.loggedInstitute;
      }
      this.http.post<any>(url, payload).subscribe({
        next: (res) => {
          this.submitting = false;
          this.loader.hide();
          this.notify.success(res?.statusMessage || 'User registered successfully');
          this.router.navigate(['/view-users']);
        },
        error: (err) => {
          this.submitting = false;
          this.loader.hide();
          console.error('Register failed', err);
          const serverMsg = err?.error?.statusMessage || err?.error?.message || err?.statusMessage || err?.message || (typeof err === 'string' ? err : null);
          this.notify.error(serverMsg ? `Failed to register user: ${serverMsg}` : 'Failed to register user.');
        }
      });
    }
  }

